import {result,download,registerResource,linkDownload} from '../ui.mjs';
export async function svgPNG(svg,width,height){const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();img.src=url;await img.decode();const c=document.createElement('canvas');c.width=width||img.naturalWidth;c.height=height||img.naturalHeight;const x=c.getContext('2d');x.drawImage(img,0,0,c.width,c.height);return await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('Could not create this PNG. Try a smaller export.')),'image/png'));}finally{URL.revokeObjectURL(url);}}
export function paperMetrics(paper='a4'){
 if(paper&&typeof paper==='object'){const w=Number(paper.widthMM),h=Number(paper.heightMM);if(!Number.isFinite(w)||!Number.isFinite(h)||w<20||h<20||w>420||h>420)throw Error('Use paper dimensions from 20 to 420 mm.');return {points:[w*72/25.4,h*72/25.4],pixels:[Math.round(w*192/25.4),Math.round(h*192/25.4)],css:w+'mm '+h+'mm',widthCSS:w+'mm',heightCSS:h+'mm'};}
 return paper==='letter'?{points:[612,792],pixels:[1632,2112],css:'letter',widthCSS:'8.5in',heightCSS:'11in'}:{points:[595.28,841.89],pixels:[1588,2246],css:'A4',widthCSS:'210mm',heightCSS:'297mm'};
}
export async function createVectorPDF(pages,paper,rasterize,PDFDocument,isCurrent=()=>true){
 if(!pages.length)throw Error('Add at least one printable page.');const doc=await PDFDocument.create(),spec=paperMetrics(paper),size=spec.points;doc.setTitle('Printable pages · Nepocore');doc.setAuthor('Nepocore');
 for(const svg of pages){if(!isCurrent())throw Error('Export cancelled.');const png=await rasterize(svg,...spec.pixels),image=await doc.embedPng(await png.arrayBuffer()),page=doc.addPage(size);page.drawImage(image,{x:0,y:0,width:size[0],height:size[1]});}return doc.save();
}
export function vectorResult(out,svg,name,{width,height,details=[],note='',extra='',label='Your design'}={}){
 result(out,{label,html:'<div class="vector-preview">'+svg+'</div><div class="result-actions"><button type="button" class="btn primary" data-vector-png>Download PNG</button><button type="button" class="btn secondary" data-vector-svg>Download SVG</button></div>'+extra,details,note});
 out.querySelector('[data-vector-svg]').onclick=()=>download(new Blob([svg],{type:'image/svg+xml'}),name+'.svg');
 out.querySelector('[data-vector-png]').onclick=async ev=>{const b=ev.currentTarget;try{b.disabled=true;b.textContent='Preparing PNG…';const blob=await svgPNG(svg,width,height);if(b.isConnected)download(blob,name+'.png');}catch(ex){if(b.isConnected){const p=document.createElement('p');p.className='form-note';p.textContent=ex.message;out.append(p);}}finally{if(b.isConnected){b.disabled=false;b.textContent='Download PNG';}}};
}
export function printVectorPages(out,pages,paper='a4',filename='nepocore-worksheets.pdf'){
 let frame;const b=document.createElement('button');b.className='btn secondary';b.textContent='Print / Save PDF';b.onclick=()=>{frame?.remove();frame=document.createElement('iframe');frame.className='print-frame';frame.title='Printable pages';frame.srcdoc='<!doctype html><html><head><meta charset="utf-8"><title>Nepocore printable pages</title><style>@page{size:'+paperMetrics(paper).css+';margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0}section{break-after:page;page-break-after:always;width:'+paperMetrics(paper).widthCSS+';height:'+paperMetrics(paper).heightCSS+';overflow:hidden}section:last-child{break-after:auto;page-break-after:auto}svg{display:block;width:100%;height:100%}</style></head><body>'+pages.map(svg=>'<section>'+svg+'</section>').join('')+'</body></html>';frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();};document.body.append(frame);};out.querySelector('.result-actions').append(b);registerResource(out,()=>frame?.remove());
 const pdf=document.createElement('button');pdf.className='btn primary';pdf.textContent='Download PDF';out.querySelector('[data-vector-png]').className='btn secondary';out.querySelector('.result-actions').prepend(pdf);pdf.onclick=async()=>{pdf.disabled=true;pdf.textContent='Preparing PDF…';try{const {loadScript}=await import('../extras.mjs'),{PDFDocument}=await loadScript('./assets/vendor/pdf-lib.min.js','PDFLib'),bytes=await createVectorPDF(pages,paper,svgPNG,PDFDocument,()=>pdf.isConnected);if(pdf.isConnected){pdf.textContent='Download PDF';linkDownload(pdf,new Blob([bytes],{type:'application/pdf'}),filename);out.querySelector('a[download="'+filename+'"]').click();}}catch(ex){if(pdf.isConnected){const p=document.createElement('p');p.className='form-note';p.textContent='PDF export could not finish: '+ex.message+'. You can still download PNG/SVG or use Print / Save PDF.';out.append(p);}}finally{if(pdf.isConnected){pdf.disabled=false;pdf.textContent='Download PDF';}}};
}
